// GENERATED by `idealyst run ios --aas`. On load,
// `ios_main(view, endpoint)` connects to the dev-server at the URL
// the CLI baked into Info.plist as `IdealystDevEndpoint`.
//
// The endpoint is set by `idealyst dev` based on (a) the dev-server's
// actual bound port (read from its port-file sentinel) and (b) the
// host's LAN IP (for device builds) or `localhost`/`10.0.2.2` (for
// simulator / emulator). Rebuilding via `idealyst dev` is the only
// way to change which dev-server this build connects to.

import UIKit

/// Resolves the dev-server URL the wrapper should connect to. Lives
/// in Info.plist so device builds don't need a fresh Rust compile
/// to change which host they target — `plutil -replace
/// IdealystDevEndpoint -string ws://…` and reinstall.
private func resolveEndpoint() -> String {
    if let s = Bundle.main.object(forInfoDictionaryKey: "IdealystDevEndpoint") as? String,
       !s.isEmpty
    {
        return s
    }
    // Empty fallback — the CLI always writes this key. Reaching here
    // means the build wasn't done through `idealyst dev`; ios_main
    // bails with a clear error message rather than connecting to
    // nothing.
    return ""
}

class ViewController: UIViewController {
    /// See the `--local` `ViewController` — same `applyFullscreen(_:)`
    /// contract so `set_fullscreen` works under the runtime-server client too.
    private var fullscreenEnabled = false

    override var prefersStatusBarHidden: Bool { fullscreenEnabled }
    override var prefersHomeIndicatorAutoHidden: Bool { fullscreenEnabled }

    @objc func applyFullscreen(_ enabled: Bool) {
        guard fullscreenEnabled != enabled else { return }
        fullscreenEnabled = enabled
        setNeedsStatusBarAppearanceUpdate()
        setNeedsUpdateOfHomeIndicatorAutoHidden()
    }

    /// Driven from Rust via `applyPointerLock(_:)` (the iOS backend's
    /// `AppEnvOps::set_pointer_lock`, i.e. the author's
    /// `request_pointer_lock()`). iPadOS grants the lock only to a
    /// full-screen, foreground scene with a pointer attached; the backend
    /// learns the outcome from `UIPointerLockStateDidChangeNotification`.
    /// Soft-failed on the Rust side (`respondsToSelector:`) for a
    /// `ViewController` generated before this method existed.
    private var pointerLockWanted = false

    override var prefersPointerLocked: Bool { pointerLockWanted }

    @objc func applyPointerLock(_ locked: Bool) {
        guard pointerLockWanted != locked else { return }
        pointerLockWanted = locked
        setNeedsUpdateOfPrefersPointerLocked()
    }

    override func viewDidLoad() {
        super.viewDidLoad()
        view.backgroundColor = .white
        mountRuntimeServerClient()
    }

    deinit {
        ios_teardown()
    }

    private func mountRuntimeServerClient() {
        let rootPtr = Unmanaged.passUnretained(view).toOpaque()
        let endpoint = resolveEndpoint()
        endpoint.withCString { cstr in
            ios_main(rootPtr, cstr)
        }
    }
}
